    logic conv_128b_rlast;
    logic conv_128b_rvalid;

    // Master-side AXIL alignment (no aggregation): every narrow
    // single-beat AXIL write becomes one wide AXI4 single-beat with
    // wdata/wstrb shifted by awaddr's low bits.
    axil_to_axi4_wide_align_wr #(
        .S_AXI_DATA_WIDTH(32),
        .M_AXI_DATA_WIDTH(128),
        .AXI_ID_WIDTH(1),
        .AXI_ADDR_WIDTH(32),
        .AXI_USER_WIDTH(1)
    ) u_wr_conv_128b (
        .aclk(aclk),
        .aresetn(aresetn),
        .s_axi_awid(fub_axi_awid),
        .s_axi_awaddr(fub_axi_awaddr),
        .s_axi_awlen(fub_axi_awlen),
        .s_axi_awsize(fub_axi_awsize),
        .s_axi_awburst(fub_axi_awburst),
        .s_axi_awlock(fub_axi_awlock),
        .s_axi_awcache(fub_axi_awcache),
        .s_axi_awprot(fub_axi_awprot),
        .s_axi_awqos(4'b0),
        .s_axi_awregion(4'b0),
        .s_axi_awuser(1'b0),
        .s_axi_awvalid(fub_axi_awvalid && aw_path_active_128b),
        .s_axi_awready(conv_128b_awready),
        .s_axi_wdata(fub_axi_wdata),
        .s_axi_wstrb(fub_axi_wstrb),
        .s_axi_wlast(fub_axi_wlast),
        .s_axi_wuser(1'b0),
        .s_axi_wvalid(fub_axi_wvalid && w_path_active_128b),
        .s_axi_wready(conv_128b_wready),
        .s_axi_bid(conv_128b_bid),
        .s_axi_bresp(conv_128b_bresp),
        .s_axi_buser(),
        .s_axi_bvalid(conv_128b_bvalid),
        .s_axi_bready(fub_axi_bready && b_path_active_128b),
        .m_axi_awid(host_128b_aw.id),
        .m_axi_awaddr(host_128b_aw.addr),
        .m_axi_awlen(host_128b_aw.len),
        .m_axi_awsize(host_128b_aw.size),
        .m_axi_awburst(host_128b_aw.burst),
        .m_axi_awlock(host_128b_aw.lock),
        .m_axi_awcache(host_128b_aw.cache),
        .m_axi_awprot(host_128b_aw.prot),
        .m_axi_awqos(host_128b_aw.qos),
        .m_axi_awregion(host_128b_aw.region),
        .m_axi_awuser(host_128b_aw.user),
        .m_axi_awvalid(host_128b_awvalid),
        .m_axi_awready(host_128b_awready),
        .m_axi_wdata(host_128b_w.data),
        .m_axi_wstrb(host_128b_w.strb),
        .m_axi_wlast(host_128b_w.last),
        .m_axi_wuser(host_128b_w.user),
        .m_axi_wvalid(host_128b_wvalid),
        .m_axi_wready(host_128b_wready),
        .m_axi_bid(host_128b_b.id),
        .m_axi_bresp(host_128b_b.resp),
        .m_axi_buser(host_128b_b.user),
        .m_axi_bvalid(host_128b_bvalid),
        .m_axi_bready(host_128b_bready)
    );

    // Master-side AXIL alignment (read direction).
    axil_to_axi4_wide_align_rd #(
        .S_AXI_DATA_WIDTH(32),
        .M_AXI_DATA_WIDTH(128),
        .AXI_ID_WIDTH(1),
        .AXI_ADDR_WIDTH(32),
        .AXI_USER_WIDTH(1)
    ) u_rd_conv_128b (
        .aclk(aclk),
        .aresetn(aresetn),
        .s_axi_arid(fub_axi_arid),
        .s_axi_araddr(fub_axi_araddr),
        .s_axi_arlen(fub_axi_arlen),
        .s_axi_arsize(fub_axi_arsize),
        .s_axi_arburst(fub_axi_arburst),
        .s_axi_arlock(fub_axi_arlock),
        .s_axi_arcache(fub_axi_arcache),
        .s_axi_arprot(fub_axi_arprot),
        .s_axi_arqos(4'b0),
        .s_axi_arregion(4'b0),
        .s_axi_aruser(1'b0),
        .s_axi_arvalid(fub_axi_arvalid && ar_path_active_128b),
        .s_axi_arready(conv_128b_arready),
        .s_axi_rid(conv_128b_rid),
        .s_axi_rdata(conv_128b_rdata),
        .s_axi_rresp(conv_128b_rresp),
        .s_axi_rlast(conv_128b_rlast),
        .s_axi_ruser(),
        .s_axi_rvalid(conv_128b_rvalid),
        .s_axi_rready(fub_axi_rready && r_path_active_128b),
        .m_axi_arid(host_128b_ar.id),
        .m_axi_araddr(host_128b_ar.addr),
        .m_axi_arlen(host_128b_ar.len),
        .m_axi_arsize(host_128b_ar.size),
        .m_axi_arburst(host_128b_ar.burst),
        .m_axi_arlock(host_128b_ar.lock),
        .m_axi_arcache(host_128b_ar.cache),
        .m_axi_arprot(host_128b_ar.prot),
        .m_axi_arqos(host_128b_ar.qos),
        .m_axi_arregion(host_128b_ar.region),
        .m_axi_aruser(host_128b_ar.user),
        .m_axi_arvalid(host_128b_arvalid),
        .m_axi_arready(host_128b_arready),
        .m_axi_rid(host_128b_r.id),
        .m_axi_rdata(host_128b_r.data),
        .m_axi_rresp(host_128b_r.resp),
        .m_axi_rlast(host_128b_r.last),
        .m_axi_ruser(host_128b_r.user),
        .m_axi_rvalid(host_128b_rvalid),
        .m_axi_rready(host_128b_rready)
    );

    // ================================================================
    // Response MUX - Route responses from width-specific paths
    // back to fub_axi_* based on address decode
    //
    // Request side (arready/awready/wready) uses the combinational
    // slave_select_{ar,aw} (valid while {ar,aw}valid is asserted).
    //
    // Response side (rvalid/rdata/..., bvalid/bid/...) cannot reuse
    // the combinational decode because fub_axi_{ar,aw}addr no longer
    // holds the request address once the {AR,AW} handshake completes
    // -- the decode reverts (typically to slave 0) and drops the
    // response. So we track slave_select_{ar,aw} per outstanding
    // request in a small FIFO captured at handshake, popped at
    // R-last / B; the FIFO head drives the response MUX.
    // ================================================================

    // OUTPUT slave_select_aw mirrors the live combinational decode.
    assign slave_select_aw = comb_slave_select_aw;

    localparam int AW_TRK_DEPTH = 16;
    localparam int AW_TRK_AW    = 4;
    // -------- AW per-ID target table (fixes bridge GitHub #119 L1) --------
    // 2 entries indexed by the ID's low 1 bit(s). An ID with requests
    // in flight may only add more to the SAME slave (AXI same-ID order);
    // any other ID may go to any slave. IDs that share the index bits are
    // treated as one ID: safe, at worst a needless stall.
    localparam int AW_IDT_N = 2;
    logic [AW_TRK_AW:0]   aw_idt_cnt [AW_IDT_N];
    logic [NUM_SLAVES-1:0] aw_idt_tgt [AW_IDT_N];
    logic [AW_TRK_AW:0]   aw_out_cnt;
    logic [0:0] aw_idt_widx, aw_idt_ridx;
    logic aw_idt_push, aw_idt_pop;
    assign aw_idt_widx = fub_axi_awid[0:0];
    assign aw_idt_ridx = fub_axi_bid[0:0];
    assign aw_idt_push = fub_axi_awvalid && fub_axi_awready;
    assign aw_idt_pop  = fub_axi_bvalid && fub_axi_bready;

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            for (int i = 0; i < AW_IDT_N; i++) begin
                aw_idt_cnt[i] <= '0;
                aw_idt_tgt[i] <= '0;
            end
            aw_out_cnt <= '0;
        end else begin
            if (aw_idt_push) aw_idt_tgt[aw_idt_widx] <= comb_slave_select_aw;
            for (int i = 0; i < AW_IDT_N; i++) begin
                aw_idt_cnt[i] <= aw_idt_cnt[i]
                    + (AW_TRK_AW+1)'(aw_idt_push && (aw_idt_widx == 1'(i)))
                    - (AW_TRK_AW+1)'(aw_idt_pop  && (aw_idt_ridx == 1'(i)));
            end
            aw_out_cnt <= aw_out_cnt + (AW_TRK_AW+1)'(aw_idt_push)
                                          - (AW_TRK_AW+1)'(aw_idt_pop);
        end
    )

    // bridge BUG-009 (was BRIDGE-011): a bounded number in flight, so no
    // count wraps; AW_TRK_DEPTH is the port's outstanding limit.
    logic aw_trk_full, aw_id_ok;
    assign aw_trk_full = (aw_out_cnt == (AW_TRK_AW+1)'(AW_TRK_DEPTH));
    assign aw_id_ok    = (aw_idt_cnt[aw_idt_widx] == '0) ||
                           (aw_idt_tgt[aw_idt_widx] == comb_slave_select_aw);

    // -------- B path arbiter (fixes bridge GitHub #119 L1) --------
    // Round robin over the 2 width paths. A grant holds while its
    // response is offered and not taken.
    logic [1:0] b_pv, b_pgnt, r_b_held;
    logic           r_b_hold;
    logic [0:0] r_b_last;
    assign b_pv[0] = host_32b_bvalid;  // 32b path
    assign b_pv[1] = conv_128b_bvalid;  // 128b path
    always_comb begin
        b_pgnt = '0;
        if (r_b_hold) begin
            b_pgnt = r_b_held;
        end else begin
            case (r_b_last)
                1'd0: begin
                    if (b_pv[0]) b_pgnt = 2'b01;
                    if (b_pv[1]) b_pgnt = 2'b10;
                end
                1'd1: begin
                    if (b_pv[1]) b_pgnt = 2'b10;
                    if (b_pv[0]) b_pgnt = 2'b01;
                end
                default: ;
            endcase
        end
    end

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            r_b_hold <= 1'b0;
            r_b_held <= '0;
            r_b_last <= '0;
        end else begin
            r_b_hold <= fub_axi_bvalid && !fub_axi_bready;
            r_b_held <= b_pgnt;
            if (fub_axi_bvalid && fub_axi_bready) begin
                if (b_pgnt[0]) r_b_last <= 1'd0;
                if (b_pgnt[1]) r_b_last <= 1'd1;
            end
        end
    )

    assign b_slave_select = ({NUM_SLAVES{b_pgnt[0]}} & 7'b0000001)
                          | ({NUM_SLAVES{b_pgnt[1]}} & 7'b0000100);

    // -------- AW->W slave_select tracking FIFO --------
    // Same push as AW (records slave_select at handshake);
    // pops on wlast so W#2's path-active gating doesn't wait
    // for B#1 to return. Without this, back-to-back writes
    // to different-width slaves stamp W#2's data on AW#1's
    // bucket (see multi-master 128b->32b/128b regression).
    logic [NUM_SLAVES-1:0] w_trk_mem [AW_TRK_DEPTH];
    logic [AW_TRK_AW:0] w_trk_wptr, w_trk_rptr;
    logic w_trk_push, w_trk_pop;

    assign w_trk_push = fub_axi_awvalid && fub_axi_awready;
    assign w_trk_pop  = fub_axi_wvalid && fub_axi_wready && fub_axi_wlast;

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            w_trk_wptr <= '0;
            w_trk_rptr <= '0;
        end else begin
            if (w_trk_push) begin
                w_trk_mem[w_trk_wptr[AW_TRK_AW-1:0]] <= comb_slave_select_aw;
                w_trk_wptr <= w_trk_wptr + 1'b1;
            end
            if (w_trk_pop) begin
                w_trk_rptr <= w_trk_rptr + 1'b1;
            end
        end
    )

    assign w_slave_select = (w_trk_wptr != w_trk_rptr)
                          ? w_trk_mem[w_trk_rptr[AW_TRK_AW-1:0]]
                          : '0;

    // A new AW may target a different slave only once every W burst
    // already accepted has gone: W carries no ID and follows AW order,
    // so two masters each with W owed to two slaves could otherwise
    // wait on each other at the slaves' W ports (crossed W deadlock).
    assign aw_gate_ok = aw_id_ok && !aw_trk_full &&
                        ((w_trk_wptr == w_trk_rptr) ||
                         (w_slave_select == comb_slave_select_aw));

    // OUTPUT slave_select_ar mirrors the live combinational decode.
    assign slave_select_ar = comb_slave_select_ar;

    localparam int AR_TRK_DEPTH = 16;
    localparam int AR_TRK_AW    = 4;
    // -------- AR per-ID target table (fixes bridge GitHub #119 L1) --------
    // 2 entries indexed by the ID's low 1 bit(s). An ID with requests
    // in flight may only add more to the SAME slave (AXI same-ID order);
    // any other ID may go to any slave. IDs that share the index bits are
    // treated as one ID: safe, at worst a needless stall.
    localparam int AR_IDT_N = 2;
    logic [AR_TRK_AW:0]   ar_idt_cnt [AR_IDT_N];
    logic [NUM_SLAVES-1:0] ar_idt_tgt [AR_IDT_N];
    logic [AR_TRK_AW:0]   ar_out_cnt;
    logic [0:0] ar_idt_widx, ar_idt_ridx;
    logic ar_idt_push, ar_idt_pop;
    assign ar_idt_widx = fub_axi_arid[0:0];
    assign ar_idt_ridx = fub_axi_rid[0:0];
    assign ar_idt_push = fub_axi_arvalid && fub_axi_arready;
    assign ar_idt_pop  = fub_axi_rvalid && fub_axi_rready && fub_axi_rlast;

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            for (int i = 0; i < AR_IDT_N; i++) begin
                ar_idt_cnt[i] <= '0;
                ar_idt_tgt[i] <= '0;
            end
            ar_out_cnt <= '0;
        end else begin
            if (ar_idt_push) ar_idt_tgt[ar_idt_widx] <= comb_slave_select_ar;
            for (int i = 0; i < AR_IDT_N; i++) begin
                ar_idt_cnt[i] <= ar_idt_cnt[i]
                    + (AR_TRK_AW+1)'(ar_idt_push && (ar_idt_widx == 1'(i)))
                    - (AR_TRK_AW+1)'(ar_idt_pop  && (ar_idt_ridx == 1'(i)));
            end
            ar_out_cnt <= ar_out_cnt + (AR_TRK_AW+1)'(ar_idt_push)
                                          - (AR_TRK_AW+1)'(ar_idt_pop);
        end
    )

    // bridge BUG-009 (was BRIDGE-011): a bounded number in flight, so no
    // count wraps; AR_TRK_DEPTH is the port's outstanding limit.
    logic ar_trk_full, ar_id_ok;
    assign ar_trk_full = (ar_out_cnt == (AR_TRK_AW+1)'(AR_TRK_DEPTH));
    assign ar_id_ok    = (ar_idt_cnt[ar_idt_widx] == '0) ||
                           (ar_idt_tgt[ar_idt_widx] == comb_slave_select_ar);
    assign ar_gate_ok = ar_id_ok && !ar_trk_full;

    // -------- R path arbiter (fixes bridge GitHub #119 L1) --------
    // Round robin over the 2 width paths. A grant holds while its
    // response is offered and not taken, and through RLAST.
    logic [1:0] r_pv, r_pgnt, r_r_held;
    logic           r_r_hold;
    logic [0:0] r_r_last;
    assign r_pv[0] = host_32b_rvalid;  // 32b path
    assign r_pv[1] = conv_128b_rvalid;  // 128b path
    always_comb begin
        r_pgnt = '0;
        if (r_r_hold) begin
            r_pgnt = r_r_held;
        end else begin
            case (r_r_last)
                1'd0: begin
                    if (r_pv[0]) r_pgnt = 2'b01;
                    if (r_pv[1]) r_pgnt = 2'b10;
                end
                1'd1: begin
                    if (r_pv[1]) r_pgnt = 2'b10;
                    if (r_pv[0]) r_pgnt = 2'b01;
                end
                default: ;
            endcase
        end
    end

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            r_r_hold <= 1'b0;
            r_r_held <= '0;
            r_r_last <= '0;
        end else begin
            r_r_hold <= r_r_hold
                ? !(fub_axi_rvalid && fub_axi_rready && fub_axi_rlast)
                : (fub_axi_rvalid && !(fub_axi_rready && fub_axi_rlast));
            r_r_held <= r_pgnt;
            if (fub_axi_rvalid && fub_axi_rready) begin
                if (r_pgnt[0]) r_r_last <= 1'd0;
                if (r_pgnt[1]) r_r_last <= 1'd1;
            end
        end
    )

    assign r_slave_select = ({NUM_SLAVES{r_pgnt[0]}} & 7'b0000001)
                          | ({NUM_SLAVES{r_pgnt[1]}} & 7'b0000100);

    // AW-ready MUX (combinational comb_slave_select_aw — awaddr is live during awvalid)
    always_comb begin
        fub_axi_awready = 1'b0;
        case (comb_slave_select_aw)
            7'b0000001: begin  // Slave 0 (32b)
                fub_axi_awready = host_32b_awready;
            end
            7'b0000010: begin  // Slave 1 (32b)
                fub_axi_awready = host_32b_awready;
            end
            7'b0001000: begin  // Slave 3 (32b)
                fub_axi_awready = host_32b_awready;
            end
            7'b0010000: begin  // Slave 4 (32b)
                fub_axi_awready = host_32b_awready;
            end
            7'b0100000: begin  // Slave 5 (32b)
                fub_axi_awready = host_32b_awready;
            end
            7'b0000100: begin  // Slave 2 (128b)
                fub_axi_awready = conv_128b_awready;
            end
            7'b1000000: begin  // Slave 6 (128b)
                fub_axi_awready = conv_128b_awready;
            end
            default: begin
                // No slave selected
            end
        endcase
        // Hold off a new AW the gate refuses (see aw_gate_ok).
        if (!aw_gate_ok) fub_axi_awready = 1'b0;
    end

    // W-ready MUX (FIFO-tracked w_slave_select — awaddr has already reverted by W phase)
    always_comb begin
        fub_axi_wready = 1'b0;
        case (w_slave_select)
            7'b0000001: begin  // Slave 0 (32b)
                fub_axi_wready = host_32b_wready;
            end
            7'b0000010: begin  // Slave 1 (32b)
                fub_axi_wready = host_32b_wready;
            end
            7'b0001000: begin  // Slave 3 (32b)
                fub_axi_wready = host_32b_wready;
            end
            7'b0010000: begin  // Slave 4 (32b)
                fub_axi_wready = host_32b_wready;
            end
            7'b0100000: begin  // Slave 5 (32b)
                fub_axi_wready = host_32b_wready;
            end
            7'b0000100: begin  // Slave 2 (128b)
                fub_axi_wready = conv_128b_wready;
            end
            7'b1000000: begin  // Slave 6 (128b)
                fub_axi_wready = conv_128b_wready;
            end
            default: begin
                // No active W transaction
            end
        endcase
    end

    // Write response MUX (B channel - uses b_slave_select FIFO head)
    always_comb begin
        fub_axi_bid = 1'd0;
        fub_axi_bresp = 2'b00;
        fub_axi_bvalid = 1'b0;

        case (b_slave_select)
            7'b0000001: begin  // Slave 0 (32b)
                fub_axi_bid = host_32b_b.id[0:0];
                fub_axi_bresp = host_32b_b.resp;
                fub_axi_bvalid = host_32b_bvalid;
            end
            7'b0000010: begin  // Slave 1 (32b)
                fub_axi_bid = host_32b_b.id[0:0];
                fub_axi_bresp = host_32b_b.resp;
                fub_axi_bvalid = host_32b_bvalid;
            end
            7'b0001000: begin  // Slave 3 (32b)
                fub_axi_bid = host_32b_b.id[0:0];
                fub_axi_bresp = host_32b_b.resp;
                fub_axi_bvalid = host_32b_bvalid;
            end
            7'b0010000: begin  // Slave 4 (32b)
                fub_axi_bid = host_32b_b.id[0:0];
                fub_axi_bresp = host_32b_b.resp;
                fub_axi_bvalid = host_32b_bvalid;
            end
            7'b0100000: begin  // Slave 5 (32b)
                fub_axi_bid = host_32b_b.id[0:0];
                fub_axi_bresp = host_32b_b.resp;
                fub_axi_bvalid = host_32b_bvalid;
            end
            7'b0000100: begin  // Slave 2 (128b)
                fub_axi_bid = conv_128b_bid;
                fub_axi_bresp = conv_128b_bresp;
                fub_axi_bvalid = conv_128b_bvalid;
            end
            7'b1000000: begin  // Slave 6 (128b)
                fub_axi_bid = conv_128b_bid;
                fub_axi_bresp = conv_128b_bresp;
                fub_axi_bvalid = conv_128b_bvalid;
            end
            default: begin
                // No slave selected - hold defaults
            end
        endcase
    end

    // AR-ready MUX (request side: uses combinational comb_slave_select_ar)
    always_comb begin
        fub_axi_arready = 1'b0;
        case (comb_slave_select_ar)
            7'b0000001: begin  // Slave 0 (32b)
                fub_axi_arready = host_32b_arready;
            end
            7'b0000010: begin  // Slave 1 (32b)
                fub_axi_arready = host_32b_arready;
            end
            7'b0001000: begin  // Slave 3 (32b)
                fub_axi_arready = host_32b_arready;
            end
            7'b0010000: begin  // Slave 4 (32b)
                fub_axi_arready = host_32b_arready;
            end
            7'b0100000: begin  // Slave 5 (32b)
                fub_axi_arready = host_32b_arready;
            end
            7'b0000100: begin  // Slave 2 (128b)
                fub_axi_arready = conv_128b_arready;
            end
            7'b1000000: begin  // Slave 6 (128b)
                fub_axi_arready = conv_128b_arready;
            end
            default: begin
                // No slave selected
            end
        endcase
        // Hold off a new AR the gate refuses (see ar_gate_ok).
        if (!ar_gate_ok) fub_axi_arready = 1'b0;
    end

    // Read response MUX (R channel - uses r_slave_select FIFO head)
    always_comb begin
        fub_axi_rid = 1'd0;
        fub_axi_rdata = 32'd0;
        fub_axi_rresp = 2'b00;
        fub_axi_rlast = 1'b0;
        fub_axi_rvalid = 1'b0;

        case (r_slave_select)
            7'b0000001: begin  // Slave 0 (32b)
                fub_axi_rid = host_32b_r.id[0:0];
                fub_axi_rdata = host_32b_r.data;
                fub_axi_rresp = host_32b_r.resp;
                fub_axi_rlast = host_32b_r.last;
                fub_axi_rvalid = host_32b_rvalid;
            end
            7'b0000010: begin  // Slave 1 (32b)
                fub_axi_rid = host_32b_r.id[0:0];
                fub_axi_rdata = host_32b_r.data;
                fub_axi_rresp = host_32b_r.resp;
                fub_axi_rlast = host_32b_r.last;
                fub_axi_rvalid = host_32b_rvalid;
            end
            7'b0001000: begin  // Slave 3 (32b)
                fub_axi_rid = host_32b_r.id[0:0];
                fub_axi_rdata = host_32b_r.data;
                fub_axi_rresp = host_32b_r.resp;
                fub_axi_rlast = host_32b_r.last;
                fub_axi_rvalid = host_32b_rvalid;
            end
            7'b0010000: begin  // Slave 4 (32b)
                fub_axi_rid = host_32b_r.id[0:0];
                fub_axi_rdata = host_32b_r.data;
                fub_axi_rresp = host_32b_r.resp;
                fub_axi_rlast = host_32b_r.last;
                fub_axi_rvalid = host_32b_rvalid;
            end
            7'b0100000: begin  // Slave 5 (32b)
                fub_axi_rid = host_32b_r.id[0:0];
                fub_axi_rdata = host_32b_r.data;
                fub_axi_rresp = host_32b_r.resp;
                fub_axi_rlast = host_32b_r.last;
                fub_axi_rvalid = host_32b_rvalid;
            end
            7'b0000100: begin  // Slave 2 (128b)
                fub_axi_rid = conv_128b_rid;
                fub_axi_rdata = conv_128b_rdata;
                fub_axi_rresp = conv_128b_rresp;
                fub_axi_rlast = conv_128b_rlast;
                fub_axi_rvalid = conv_128b_rvalid;
            end
            7'b1000000: begin  // Slave 6 (128b)
                fub_axi_rid = conv_128b_rid;
                fub_axi_rdata = conv_128b_rdata;
                fub_axi_rresp = conv_128b_rresp;
                fub_axi_rlast = conv_128b_rlast;
                fub_axi_rvalid = conv_128b_rvalid;
            end
            default: begin
                // No slave selected - hold defaults
            end
        endcase
    end


    // -------- ILA observation taps (AMBER_ILA_DBG builds only) --------
    // Amber bring-up round 5: name the adapter-internal AR tracker,
    // AR gate, and read-wrapper terms post-synth so the board ILA can
    // distinguish a corrupted ar_trk_full from a wedged axi4_slave_rd.
    // Pure observation; compiled out unless AMBER_ILA_DBG is defined.
`ifdef AMBER_ILA_DBG
    (* mark_debug = "true" *) logic             dbg_ad_ar_trk_full;
    (* mark_debug = "true" *) logic [AR_TRK_AW:0] dbg_ad_ar_trk_wptr;
    (* mark_debug = "true" *) logic [AR_TRK_AW:0] dbg_ad_ar_trk_rptr;
    (* mark_debug = "true" *) logic             dbg_ad_ar_gate_ok;
    (* mark_debug = "true" *) logic             dbg_ad_ar_push;
    (* mark_debug = "true" *) logic             dbg_ad_ar_pop;
    (* mark_debug = "true" *) logic             dbg_ad_host_arvalid;
    (* mark_debug = "true" *) logic             dbg_ad_host_arready;
    (* mark_debug = "true" *) logic             dbg_ad_fub_arvalid;
    (* mark_debug = "true" *) logic             dbg_ad_fub_arready;
    (* mark_debug = "true" *) logic             dbg_ad_wrapper_rd_busy;
    (* mark_debug = "true" *) logic             dbg_ad_fub_rvalid;
    (* mark_debug = "true" *) logic             dbg_ad_fub_rready;
    (* mark_debug = "true" *) logic             dbg_ad_fub_rlast;

    assign dbg_ad_ar_trk_full      = ar_trk_full;
    assign dbg_ad_ar_trk_wptr      = ar_trk_wptr;
    assign dbg_ad_ar_trk_rptr      = ar_trk_rptr;
    assign dbg_ad_ar_gate_ok       = ar_gate_ok;
    assign dbg_ad_ar_push          = ar_trk_push;
    assign dbg_ad_ar_pop           = ar_trk_pop;
    assign dbg_ad_host_arvalid     = host_axi_arvalid;
    assign dbg_ad_host_arready     = host_axi_arready;
    assign dbg_ad_fub_arvalid      = fub_axi_arvalid;
    assign dbg_ad_fub_arready      = fub_axi_arready;
    assign dbg_ad_wrapper_rd_busy  = wrapper_rd_busy;
    assign dbg_ad_fub_rvalid       = fub_axi_rvalid;
    assign dbg_ad_fub_rready       = fub_axi_rready;
    assign dbg_ad_fub_rlast        = fub_axi_rlast;
`endif

endmodule : bridge_fb_cfg_host_adapter
